        {
            actionExt.hasStages = true;
        }
        else
        {
            actionExt.hasStages = false;
        }
        actionExt.canEdit = false;
        if (myuser!=null && myuser.IsAdmin==true)
        {
            actionExt.canEdit = true;
        }
        actionWithStates.Add(actionExt);
    }
    return await Task.Run(()=>actionWithStates);
